const SEVERITY_ESCALATION_DAYS = { Low: 2, Medium: 5, High: 10 };

/* ============================== HELPERS ============================== */
const uid = () => Math.random().toString(36).slice(2, 10);
const todayStr = () => new Date().toISOString().slice(0, 10);
const daysBetween = (a, b) => (new Date(b) - new Date(a)) / 86400000;
const addDaysStr = (dateStr, n) => new Date(new Date(dateStr).getTime() + n * 86400000).toISOString().slice(0, 10);

const isWeekendDay = (dateStr) => {
  const d = new Date(dateStr).getDay();
  return d === 0 || d === 6;
};
const rollToWorkingDay = (dateStr, worksWeekends) => {
  if (worksWeekends) return dateStr;
  let d = dateStr;
  while (isWeekendDay(d)) d = addDaysStr(d, 1);
  return d;
};
const addWorkingDaysStr = (startStr, n, worksWeekends) => {
  if (worksWeekends) return addDaysStr(startStr, n);
  let d = startStr;
  let remaining = n;
  while (remaining > 0) {
    d = addDaysStr(d, 1);
    if (!isWeekendDay(d)) remaining--;
  }
  return d;
};

// Two grace windows, not one. Day-shift tasks (the common case) get a 4am
// buffer. Night-shift tasks — crews still legitimately on site through the
// small hours, common for IBC building-access work when the PIC only
// allows night work — get a later cutoff so they aren't flagged red while
// still mid-shift. Tune these two numbers to match your actual ops; they're
// a starting assumption, not a measured value.
const OVERDUE_GRACE_CUTOFF_HOUR_DAY = 4;
const OVERDUE_GRACE_CUTOFF_HOUR_NIGHT = 12;

function localDateStr(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

// Returns the calendar date (local time) that should count as "today" for
// overdue checks, given whether this specific task is night-shift work.
// Does NOT change start/end date storage or the "Today" marker line on the
// chart — only which day a task's Finish date is compared against before
// it's treated as late.
function overdueEffectiveToday(isNightShift) {
  const cutoffHour = isNightShift ? OVERDUE_GRACE_CUTOFF_HOUR_NIGHT : OVERDUE_GRACE_CUTOFF_HOUR_DAY;
  const now = new Date();
  if (now.getHours() < cutoffHour) {
    now.setDate(now.getDate() - 1);
  }
  return localDateStr(now);
}

// Status drives progress + the "originally due" snapshot used to colour the
// Gantt bar — shared by TaskModal and the Gantt tab's inline status edit so
// the two can't diverge.
function statusChangePatch(task, newStatus) {
  const patch = { status: newStatus };
  const today = todayStr();

  if (newStatus === "Completed") {
    patch.progress = 100;
    // Finished past its Finish date: persist the real duration. Without
    // this, the render-time stretch (which only applies while the task is
    // still incomplete) disappears the moment it's marked Completed, and a
    // task that actually ran 3 days snaps back to showing its original
    // 1-day plan.
    if (task.end && task.end < today) {
      patch.plannedEnd = task.plannedEnd || task.end; // original due date, kept as history
      patch.end = today; // actual completion date
    }
    // plannedEnd is deliberately NOT cleared here — it's the permanent
    // record of when the task was originally due, used to render the red
    // overrun tail and the "completed Nd late" badge.
  } else if (newStatus === "Not Started") {
    patch.progress = 0;
    patch.plannedEnd = "";
  } else if (newStatus === "Delayed") {
    if (!task.plannedEnd) patch.plannedEnd = task.end || "";
  } else {
    // In Progress: manually reverting out of Delayed clears the snapshot.
    patch.plannedEnd = "";
  }
  return patch;
}

// If a task's Finish now runs past the project's own target finish date, and it isn't
// already Completed or Delayed, auto-flag it Delayed — plannedEnd snapshots the
// project's target finish (so the Gantt bar's red segment runs from the target date
// to the task's real finish). Never overwrites an existing plannedEnd, and never
// auto-reverts later if dates come back in line.
function applyTargetOverrunPatch(task, projectEndDate) {
  if (!projectEndDate || !task.end) return {};
  if (task.status === "Completed" || task.status === "Delayed") return {};
  if (task.end > projectEndDate) {
    return { status: "Delayed", plannedEnd: task.plannedEnd || projectEndDate };
  }
  return {};
}

// applyTargetOverrunPatch above deliberately skips any task that's already
// Completed or Delayed — it assumes those tasks don't need re-checking. But
// that leaves a gap: if someone directly edits the Start/Finish dates on a
// task that's ALREADY Completed (fixing a data-entry mistake, backfilling
// real dates, correcting a bad bulk-generate run), any plannedEnd it's
// carrying stays frozen at whatever it was BEFORE the edit — and every
// "completed Nd late" display then compares the freshly-edited date against
// that stale snapshot, producing a lateness figure with no relationship to
// anything the person actually did. This clears plannedEnd specifically in
// that situation, treating a direct date edit on a Completed task as a
// correction, not a delay event. A genuine "this finished late" record
// should only ever come from the two deliberate paths that already exist:
// marking a task Delayed by hand, or completing a task while its Finish
// date is still in the past (both go through statusChangePatch above, not
// this function).
function reconcilePlannedEndOnDateEdit(original, merged) {
  // Both checks matter, not just the second one. Requiring ONLY
  // merged.status === "Completed" was the bug: completing an overdue task
  // via the Status dropdown legitimately changes both status AND end in
  // the same update (that's statusChangePatch's job, and it's correct) —
  // so a date-changed check alone couldn't tell that apart from a raw
  // date-field edit, and wiped the plannedEnd statusChangePatch had just
  // set correctly. Requiring the task to have ALREADY been Completed
  // BEFORE this update too means this only fires when status genuinely
  // didn't change in this operation — i.e. only on a direct date edit to
  // an already-decided task, never on the transition into Completed.
  if (original.status !== "Completed" || merged.status !== "Completed") return {};
  const dateChanged = merged.start !== original.start || merged.end !== original.end;
  if (!dateChanged) return {};
  return { plannedEnd: "" };
}

// How many days past its Finish date a task is, right now.
function daysOverdueCount(task, todayVal) {
  if (!task.end || task.end >= todayVal || task.status === "Completed") return 0;

  return Math.max(1, Math.round(daysBetween(task.end, todayVal)));
}
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));

