// Builds one audit-log entry. There's no login system in this app, so
// accountability is role-level, not person-level — "Finance changed this,"
// not "which specific person on the Finance team." For Subcon, the company
// name is attached too, since that's the closest thing to identity that
// role has. Real named-user tracking would require building actual
// authentication first, which this doesn't attempt.
function makeLogEntry(role, subconName, summary) {
  return {
    id: uid(),
    timestamp: new Date().toISOString(),
    actor: role,
    actorDetail: role === ROLES.SUBCON ? subconName || null : null,
    summary,
  };
}

// One-line summary of a cost entry's payment terms, e.g. "40-60 · RM4,000.00 + RM6,000.00"
// or "100 · RM25,000.00". Returns null if no terms structure is set (older
// entries, or ones that never used the terms breakdown), so callers can
// decide whether to render a sub-line at all.
// Returns a per-phase breakdown for display, e.g. under 40-60 terms:
// [{ label: "First phase", targetPct: 40, amounts: [10, 10] },
//  { label: "Second phase", targetPct: 60, amounts: [] }]
// amounts only ever contains REAL entered payments (>0) — an empty or
// unfilled box doesn't show up as a misleading "RM0.00" line, it shows up
// as an empty amounts list, which the caller renders as "not yet paid".
// Returns null if there's no terms/payments data to show at all. Handles
// all three historical shapes this feature has gone through — current
// phase-nested payments[][], the flat payments[] from before phases
// existed, and the original fixed payment1/payment2 fields.
// Groups tasks by site, ordered to match the project's own site list (the
// order the Coordinator entered them in), with any site name used on a
// task but missing from that list appended after, and untagged tasks
// bucketed last under "". Shared by the live Gantt tab and the print
// report so the two can't silently drift into different groupings/orders.
function groupTasksBySite(tasks, siteNames) {
  if (!siteNames || siteNames.length === 0) return null;
  const bySite = {};
  tasks.forEach((t) => {
    const key = t.site || "";
    (bySite[key] = bySite[key] || []).push(t);
  });
  const ordered = [];
  siteNames.forEach((s) => {
    if (bySite[s]) ordered.push({ site: s, tasks: bySite[s] });
  });
  Object.keys(bySite)
    .filter((k) => k && !siteNames.includes(k))
    .forEach((k) => ordered.push({ site: k, tasks: bySite[k] }));
  if (bySite[""]) ordered.push({ site: "", tasks: bySite[""] });
  return ordered;
}

function getPaymentPhaseBreakdown(c) {
  const split = c.paymentTerms ? PAYMENT_TERMS_SPLITS[c.paymentTerms] : null;
  if (!split) return null;

  let phases;
  if (Array.isArray(c.payments) && c.payments.length > 0 && Array.isArray(c.payments[0])) {
    phases = c.payments;
  } else if (Array.isArray(c.payments) && c.payments.length > 0) {
    phases = split.map(() => []);
    c.payments.forEach((amt, i) => phases[Math.min(i, phases.length - 1)].push(amt));
  } else if (c.payment1 !== undefined || c.payment2 !== undefined) {
    phases = split.length > 1 ? [[c.payment1], [c.payment2]] : [[c.payment1]];
  } else {
    phases = [];
  }
  if (phases.length === 0) return null;

  const budgetedNum = Number(c.budgeted) || 0;

  return split.map((targetPct, idx) => {
    const amounts = (phases[idx] || []).filter((v) => v !== undefined && v !== "" && Number(v) > 0);
    const paidAmount = amounts.reduce((s, v) => s + (Number(v) || 0), 0);
    // null (not 0) when Amount is blank — "short by RM0" would be a false
    // claim of being fully paid when there's actually nothing to measure
    // against yet.
    const targetAmount = budgetedNum > 0 ? (targetPct / 100) * budgetedNum : null;
    const isShort = targetAmount != null && paidAmount < targetAmount - 0.01;
    const shortfall = isShort ? targetAmount - paidAmount : 0;
    return {
      label: split.length > 1 ? (idx === 0 ? "First phase" : "Second phase") : null,
      targetPct,
      amounts,
      paidAmount,
      targetAmount,
      isShort,
      shortfall,
    };
  });
}

// Once Finance records a decision (Approved/Rejected), the entry locks:
// Coordinator can no longer edit it, Finance can no longer delete it. Both
// exist to protect the audit trail once a call has been made — while still
// Pending, either role has full edit/delete access.
//
// NOTE: as written, the Coordinator CAN still delete a decided entry (only
// editing is locked for them). If you want nobody able to delete a decided
// entry at all, change deleteLocked to just `decided` (see note at bottom
// of chat).
function costLockState(cost, role) {
  // Admin overrides both locks outright — full control was the explicit
  // point of that role, so it doesn't inherit either restriction.
  if (role === ROLES.ADMIN) return { editLocked: false, deleteLocked: false };
  const decided = cost.approval && cost.approval !== "Pending";
  return {
    editLocked: decided && role === ROLES.COORDINATOR,
    deleteLocked: decided && role === ROLES.FINANCE,
  };
}

function calcProjectMetrics(p) {
  const costs = p.costs || [];
  const tasks = p.tasks || [];
  const issues = p.issues || [];

  const actualCost = costs
    .filter((c) => c.approval === "Approved")
    .reduce((s, c) => s + (Number(c.actual) || 0), 0);
  const budgeted = costs.reduce((s, c) => s + (Number(c.budgeted) || 0), 0);
  const contractValue = Number(p.contractValue) || 0;
  const profit = contractValue - actualCost;
  const margin = contractValue > 0 ? profit / contractValue : 0;

  const completion =
    tasks.length > 0
      ? tasks.reduce((s, t) => s + (Number(t.progress) || 0), 0) / tasks.length / 100
      : 0;

  // Each task checks overdue against its own grace window (day vs night
  // shift) — see overdueEffectiveToday. This keeps the Dashboard health
  // pill and card counts consistent with what the Gantt tab shows for the
  // same task, instead of the two disagreeing near a shift boundary.
  const overdueTasks = tasks.filter(
    (t) => t.end && t.end < overdueEffectiveToday(!!t.nightShift) && t.status !== "Completed"
  );
  const openIssues = issues.filter((i) => i.status === "Open" || i.status === "In Progress");
  const criticalOpen = openIssues.filter((i) => getEffectiveSeverity(i) === "Critical");
  const budgetUtilization = contractValue > 0 ? actualCost / contractValue : 0;

  let health = "GREEN";
  if (p.status === "Completed") {
    health = "COMPLETED";
  } else if (overdueTasks.length > 0 || criticalOpen.length > 0 || budgetUtilization > 1) {
    health = "RED";
  } else if (openIssues.length > 0 || budgetUtilization > 0.85) {
    health = "AMBER";
  }

  // Two separate axes of "done" — schedule and money — that don't
  // automatically agree with each other. A Coordinator can mark every task
  // Completed while Finance still has an approval sitting untouched, or an
  // approved cost with a payment phase that's short of its actual target.
  const allTasksCompleted = tasks.length > 0 && tasks.every((t) => t.status === "Completed");
  const pendingApprovalCount = costs.filter((c) => c.approval === "Pending").length;
  // isShort is computed once, inside getPaymentPhaseBreakdown — reused
  // here rather than re-deriving target/paid amounts a second time, so
  // this can't silently drift from what the Costs tab itself now flags.
  const unpaidPhaseCount = costs.filter((c) => {
    if (c.approval !== "Approved") return false;
    const breakdown = getPaymentPhaseBreakdown(c);
    return !!breakdown && breakdown.some((phase) => phase.isShort);
  }).length;
  const financeOpenCount = pendingApprovalCount + unpaidPhaseCount;
  const scheduleDoneFinanceOpen = allTasksCompleted && financeOpenCount > 0;

  return {
    actualCost,
    budgeted,
    contractValue,
    profit,
    margin,
    completion,
    overdueTasks,
    openIssuesCount: openIssues.length,
    budgetUtilization,
    health,
    financeOpenCount,
    pendingApprovalCount,
    unpaidPhaseCount,
    scheduleDoneFinanceOpen,
  };
}

